  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "The carboxylate-bearing spiperone analog DiPOA had a brain-to-plasma ratio of only 0.019 in rats and was explicitly described as lacking CNS efficacy due to extremely low CNS penetration, directly supporting the ionized-acid liability present in the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "A zwitterionic spiperone-derived complex showed very low brain/blood ratios (0.04–0.10) in rats, attributed to poor BBB diffusion; this supports that ionizable/zwitterionic modifications to the spiperone scaffold can abolish meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "18F-FESP, a close spiperone analog without the carboxylic acid, easily crosses the BBB in PET studies; this shows the parent scaffold is permeable but does not address the query's key carboxylate modification.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a spiperone-like scaffold carrying a free carboxylic acid. Although the parent spiperone scaffold is BBB-permeable, the closest acid-bearing analog has a brain-to-plasma ratio of 0.019 and is CNS-impenetrant, and another zwitterionic spiperone analog also shows very low brain uptake. The ionizable carboxylate is expected to dominate and prevent meaningful CNS access, so the prediction is fail.",
  "evidence_gaps": [
    "No direct brain, plasma, or CSF measurement exists for the exact query molecule.",
    "The most relevant acid-containing analog has only moderate structural similarity to the query.",
    "Possible active transport, prodrug behavior, or species-specific differences were not assessed."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

